// Command models is an untrusted leaf. It reads available models from a
// provider's local cache and returns them. It shares no code with skyra.
//
// For Codex: reads ~/.codex/models_cache.json (generated by the Codex CLI
// during bootstrap). For Claude: reads the Claude Code model catalog cache
// under ~/.claude/cache/model-catalog/.
//
// The sandbox grants read access to the cache paths through SKYRA_READ. No
// network access is needed: the caches are populated by each provider's own
// CLI during normal operation.
package main

import (
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"
	"strings"
)

type model struct {
	ID          string `json:"id"`
	Name        string `json:"name"`
	Description string `json:"description,omitempty"`
	Context     int    `json:"context,omitempty"`
}

type result struct {
	Provider string  `json:"provider"`
	Models   []model `json:"models"`
	Error    string  `json:"error,omitempty"`
}

func main() {
	var in struct {
		Provider string `json:"provider"`
	}
	if err := json.NewDecoder(os.Stdin).Decode(&in); err != nil {
		fmt.Fprintln(os.Stderr, "models:", err)
		os.Exit(1)
	}

	var r result
	r.Provider = in.Provider

	switch in.Provider {
	case "codex":
		r = codexModels(r)
	case "claude":
		r = claudeModels(r)
	default:
		r.Error = fmt.Sprintf("unknown provider %q; use \"codex\" or \"claude\"", in.Provider)
	}

	b, _ := json.Marshal(map[string]any{"to": os.Getenv("SKYRA_FRAME"), "payload": r})
	fmt.Println(string(b))
}

func codexModels(r result) result {
	home, err := os.UserHomeDir()
	if err != nil {
		r.Error = "cannot find home directory"
		return r
	}
	path := filepath.Join(home, ".codex", "models_cache.json")
	data, err := os.ReadFile(path)
	if err != nil {
		r.Error = fmt.Sprintf("cannot read Codex model cache: %v", err)
		return r
	}
	var cache struct {
		ClientVersion string `json:"client_version"`
		Models        []struct {
			Slug             string `json:"slug"`
			DisplayName      string `json:"display_name"`
			Description      string `json:"description"`
			ContextWindow    int    `json:"context_window"`
			MaxContextWindow int    `json:"max_context_window"`
		} `json:"models"`
	}
	if err := json.Unmarshal(data, &cache); err != nil {
		r.Error = fmt.Sprintf("cannot parse Codex model cache: %v", err)
		return r
	}
	for _, m := range cache.Models {
		ctx := m.ContextWindow
		if m.MaxContextWindow > ctx {
			ctx = m.MaxContextWindow
		}
		r.Models = append(r.Models, model{
			ID:          m.Slug,
			Name:        m.DisplayName,
			Description: m.Description,
			Context:     ctx,
		})
	}
	return r
}

func claudeModels(r result) result {
	home, err := os.UserHomeDir()
	if err != nil {
		r.Error = "cannot find home directory"
		return r
	}
	catalogDir := filepath.Join(home, ".claude", "cache", "model-catalog")
	entries, err := os.ReadDir(catalogDir)
	if err != nil {
		r.Error = fmt.Sprintf("cannot read Claude model catalog: %v", err)
		return r
	}
	// Find the newest catalog file (there may be several; use the one with
	// the most recent mod time whose name ends in -cc.json).
	var best string
	var bestTime int64
	for _, e := range entries {
		if e.IsDir() || !strings.HasSuffix(e.Name(), "-cc.json") {
			continue
		}
		info, err := e.Info()
		if err != nil {
			continue
		}
		if t := info.ModTime().UnixNano(); best == "" || t > bestTime {
			best = filepath.Join(catalogDir, e.Name())
			bestTime = t
		}
	}
	if best == "" {
		r.Error = "no Claude model catalog found; run claude once to populate it"
		return r
	}
	data, err := os.ReadFile(best)
	if err != nil {
		r.Error = fmt.Sprintf("cannot read Claude catalog: %v", err)
		return r
	}
	var catalog struct {
		Catalog struct {
			Config struct {
				Models []struct {
					ID          string `json:"id"`
					Name        string `json:"name"`
					Description string `json:"description"`
				} `json:"models"`
			} `json:"config"`
		} `json:"catalog"`
	}
	if err := json.Unmarshal(data, &catalog); err != nil {
		r.Error = fmt.Sprintf("cannot parse Claude catalog: %v", err)
		return r
	}
	for _, m := range catalog.Catalog.Config.Models {
		r.Models = append(r.Models, model{
			ID:          m.ID,
			Name:        m.Name,
			Description: m.Description,
		})
	}
	return r
}
